using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.CostCenters.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.CostCenters.Commands.UpdateCostCenter;public sealed class UpdateCostCenterCommandHandler(ICostCenterRepository repository,IApplicationDbContext db):IRequestHandler<UpdateCostCenterCommand,Result<CostCenterDto>>{public async Task<Result<CostCenterDto>>Handle(UpdateCostCenterCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<CostCenterDto>(CostCenterErrors.NotFound);e.Update(request.Name,request.Description,request.BranchId);e.MoveUnder(request.ParentCostCenterId);await db.SaveChangesAsync(cancellationToken);return Result.Success(CostCenterDto.FromEntity(e));}}
